  .stat-card h2 {
    font-size: 16px;
    font-weight: 600;
    color: #8b949e;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .stat-card .total { font-size: 36px; font-weight: 600; color: #e6edf3; margin-bottom: 12px; }
