    font-size: 18px;
    font-weight: 600;
    color: #e6edf3;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .table-wrapper {
    overflow-x: auto;
    border: 1px solid #30363d;
    border-radius: 8px;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    background-color: #161b22;
  }
