    background-color: #161b22;
    color: #8b949e;
    font-weight: 600;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 12px 16px;
    text-align: left;
    border-bottom: 1px solid #30363d;
  }
  td {
    padding: 12px 16px;
    border-bottom: 1px solid #21262d;
    font-size: 14px;
  }
