  }

  .hidden { display: none; }
</style>
</head>
<body>
<div class="container">
  <header id="header" class="hidden">
    <h1>📊 Repository Dashboard</h1>
    <a class="repo-link" id="repoLink" href="#" target="_blank"></a>
  </header>

  <div class="loading" id="loading">
    <div class="spinner"></div>
    <p>Loading statistics…</p>
  </div>

  <div class="error hidden" id="error">
    <span class="error-icon">⚠️</span>
    <h3>Failed to load data</h3>
    <p id="errorMessage">stats.json could not be found. Ensure the file exists in the same directory.</p>
  </div>

  <div id="content" class="hidden">
    <div class="stats-row" id="statsRow"></div>

    <div class="section" id="commitsSection">
      <h2>📝 Recent Commits</h2>
      <div class="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>SHA</th>
              <th>Message</th>
              <th>Author</th>
              <th>Date</th>
            </tr>
          </thead>
          <tbody id="commitsBody"></tbody>
        </table>
      </div>
    </div>
  </div>

  <footer id="footer" class="hidden">
    <span class="updated" id="lastUpdated"></span>
  </footer>
</div>

<script>
(async function() {
  const $ = (id) => document.getElementById(id);
  const loading = $('loading');
  const error = $('error');
  const errorMsg = $('errorMessage');
  const content = $('content');
  const header = $('header');
  const footer = $('footer');
  const repoLink = $('repoLink');
  const statsRow = $('statsRow');
  const commitsBody = $('commitsBody');
  const lastUpdated = $('lastUpdated');

  let data;
  try {
    const res = await fetch('stats.json');
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
    data = await res.json();
  } catch (e) {
    loading.classList.add('hidden');
    error.classList.remove('hidden');
    errorMsg.textContent = `stats.json could not be loaded. (${e.message})`;
    return;
  }

  loading.classList.add('hidden');
  header.classList.remove('hidden');
  content.classList.remove('hidden');
  footer.classList.remove('hidden');

  // Header
  const repo = data.repository || 'unknown/unknown';
  repoLink.textContent = repo;
  repoLink.href = `https://github.com/${repo}`;

  // Stats cards
  const issues = data.issues || {};
  const prs = data.pull_requests || {};
  const totalIssues = (issues.open || 0) + (issues.closed || 0);
  const totalPRs = (prs.open || 0) + (prs.merged || 0) + (prs.closed || 0);
  const now = new Date();

  statsRow.innerHTML = `
    <div class="stat-card">
      <h2>🐛 Issues</h2>
      <div class="total">${totalIssues}</div>
      <div class="stat-breakdown">
        <span class="badge">🟢 Open <span class="count">${issues.open || 0}</span></span>
        <span class="badge">✅ Closed <span class="count">${issues.closed || 0}</span></span>
      </div>
    </div>
    <div class="stat-card">
      <h2>🔄 Pull Requests</h2>
      <div class="total">${totalPRs}</div>
      <div class="stat-breakdown">
        <span class="badge">🟢 Open <span class="count">${prs.open || 0}</span></span>
        <span class="badge">📦 Merged <span class="count">${prs.merged || 0}</span></span>
        <span class="badge">❌ Closed <span class="count">${prs.closed || 0}</span></span>
      </div>
    </div>
  `;

  // Commits table
  const commits = data.commits || [];
  if (commits.length === 0) {
    $('commitsSection').classList.add('hidden');
  } else {
    const fmt = (iso) => {
      const d = new Date(iso);
      return isNaN(d.getTime()) ? iso : d.toLocaleDateString('ja-JP', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
    };
    commits.forEach(c => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="sha">${c.sha ? c.sha.substring(0, 7) : '-'}</td>
        <td class="message">${c.message || '-'}</td>
        <td class="author">${c.author || '-'}</td>
        <td class="date">${fmt(c.date)}</td>
      `;
      commitsBody.appendChild(tr);
    });
  }

  // Footer
  lastUpdated.textContent = `Last updated: ${now.toLocaleDateString('ja-JP', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' })}`;
})();
</script>
</body>
</html>
"}

